# ============================================================================== # JANUS PROTOCOL: ENTERPRISE EVOLUTIONARY SWARM & EXECUTION PLATFORM # Features: Multi-Threaded Genetic Optimization, Regime-Switching Classifier, # NSGA-II Multi-Objective Pareto Sorting, Walk-Forward Validation, # SQLite Persistence, Live Broker Paper Simulation, and Multi-Tab Streamlit UI. # ============================================================================== import time import os import random import sqlite3 import json import numpy as np import pandas as pd import concurrent.futures import streamlit as st # ============================================================================== # 1. CORE EVOLUTIONARY SWARM & MULTI-OBJECTIVE ENGINE # ============================================================================== class Individual: """ Represents a candidate trading strategy within the evolutionary swarm. Contains the DNA vector configuration and maps multi-objective metrics. """ def __init__(self, dna): self.dna = dna # Schema: [Indicator_Flag, Lookback_Window, Breakout_Threshold, Channel_Weight] self.val_loss = 0.0 # Objective 1: Negative Sharpe Ratio (minimize) self.max_dd = 0.0 # Objective 2: Maximum Drawdown Percentage (%) (minimize) self.tracking_jitter = 0.0# Objective 3: Mean Channel Band Width Volatility (minimize) self.pareto_rank = 0 # NSGA-II Non-Domination Rank self.crowding_distance = 0.0 class VolatilityRegimeClassifier: """ Unsupervised macro volatility state classifier. Segments market price series into structural regimes (Low Volatility Trend vs High Volatility Shock) to dynamically adjust channel sensitivity lookbacks. """ @staticmethod def classify_regimes(market_matrix, window=30): df = market_matrix.copy() returns = df['SPY_close'].pct_change().fillna(0) rolling_vol = returns.rolling(window=window).std() * np.sqrt(252) df['volatility'] = rolling_vol.bfill() # Dynamic threshold based on median volatility median_vol = df['volatility'].median() df['regime'] = df['volatility'].apply(lambda v: 'HIGH_VOL_SHOCK' if v > median_vol else 'LOW_VOL_TREND') return df class VolatilityChannelFeatureEngineer: """ Vectorized generation of multi-timeframe volatility channels with regime adjustments. """ @staticmethod def generate_multi_timeframe_channels(market_matrix, fast_window=15, slow_window=90, atr_multiplier=2.0): df = VolatilityRegimeClassifier.classify_regimes(market_matrix) prices = df['SPY_close'].values highs = prices * 1.0005 lows = prices * 0.9995 tr = np.maximum(highs[1:] - lows[1:], np.maximum(np.abs(highs[1:] - prices[:-1]), np.abs(lows[1:] - prices[:-1]))) tr = np.insert(tr, 0, tr[0]) df['fast_ema'] = df['SPY_close'].ewm(span=fast_window, adjust=False).mean() df['fast_atr'] = pd.Series(tr).ewm(span=fast_window, adjust=False).mean() # Dynamically modulate ATR multiplier based on detected macro regime regime_multiplier = df['regime'].apply(lambda r: atr_multiplier * 1.3 if r == 'HIGH_VOL_SHOCK' else atr_multiplier).values df['keltner_upper'] = df['fast_ema'] + (df['fast_atr'] * regime_multiplier) df['keltner_lower'] = df['fast_ema'] - (df['fast_atr'] * regime_multiplier) df['donchian_high'] = df['SPY_close'].rolling(window=slow_window).max() df['donchian_low'] = df['SPY_close'].rolling(window=slow_window).min() df.bfill(inplace=True) return df class MultiFactorChannelEvaluationNode: """ Evaluation engine node executing multi-timeframe channel rules with lookahead safeguards. """ @staticmethod def evaluate_channel_strategy(individual, market_matrix, execution_fee=1e-4): ind_flag, lookback_raw, breakout_thresh, channel_weight = individual.dna lookback = int(round(lookback_raw)) if lookback < 5 or breakout_thresh <= 0 or not (0.0 <= channel_weight <= 1.0): individual.val_loss, individual.max_dd, individual.tracking_jitter = 999.0, 99.0, 999.0 return individual, None try: slow_window = lookback * 4 enriched_df = VolatilityChannelFeatureEngineer.generate_multi_timeframe_channels( market_matrix, fast_window=lookback, slow_window=slow_window ) prices = enriched_df['SPY_close'].values keltner_upper = enriched_df['keltner_upper'].values keltner_lower = enriched_df['keltner_lower'].values donchian_low = enriched_df['donchian_low'].values returns = np.diff(prices) / prices[:-1] signal = np.zeros_like(returns) for i in range(slow_window, len(returns)): eval_idx = i - 1 current_price = prices[eval_idx] if current_price > keltner_upper[eval_idx] * (1.0 + breakout_thresh) and current_price > donchian_low[eval_idx]: signal[i] = 1.0 * channel_weight elif current_price < keltner_lower[eval_idx] * (1.0 - breakout_thresh): signal[i] = -1.0 * channel_weight else: signal[i] = 0.0 trade_returns = returns[slow_window:] trade_signals = signal[slow_window:] if len(trade_returns) <= 1: individual.val_loss, individual.max_dd, individual.tracking_jitter = 999.0, 99.0, 999.0 return individual, None strategy_returns = trade_signals[:-1] * trade_returns[:-1] signal_changes = np.abs(np.diff(trade_signals)) strategy_returns -= signal_changes[:-1] * execution_fee avg_ret = np.mean(strategy_returns) std_ret = np.std(strategy_returns) if np.std(strategy_returns) > 0 else 1.0 sharpe = (avg_ret / std_ret) * np.sqrt(252 * 78) individual.val_loss = -sharpe if not np.isnan(sharpe) and not np.isinf(sharpe) else 999.0 cum_returns = np.cumprod(1.0 + strategy_returns) running_max = np.maximum.accumulate(cum_returns) drawdowns = (running_max - cum_returns) / running_max individual.max_dd = float(np.max(drawdowns)) * 100.0 if len(drawdowns) > 0 else 99.0 individual.tracking_jitter = float(np.mean(keltner_upper[slow_window:] - keltner_lower[slow_window:])) return individual, signal except Exception: individual.val_loss, individual.max_dd, individual.tracking_jitter = 999.0, 99.0, 999.0 return individual, None class EvolutionaryChannelOptimizer: """ Manages genetic workflow and NSGA-II multi-objective non-dominated sorting. """ def __init__(self, population_size=32, generations=10, mutation_rate=0.25): self.population_size = population_size self.generations = generations self.mutation_rate = mutation_rate def initialize_population(self): return [Individual([ 1.0, random.uniform(10.0, 40.0), random.uniform(0.0005, 0.005), random.uniform(0.2, 1.0) ]) for _ in range(self.population_size)] def evaluate_population(self, population, market_matrix): with concurrent.futures.ThreadPoolExecutor() as executor: futures = { executor.submit(MultiFactorChannelEvaluationNode.evaluate_channel_strategy, ind, market_matrix): ind for ind in population } evaluated = [] for future in concurrent.futures.as_completed(futures): ind, _ = future.result() evaluated.append(ind) return evaluated def fast_non_dominated_sort(self, population): """NSGA-II Pareto Front Sorting across [val_loss, max_dd, tracking_jitter]""" fronts = [[]] for p in population: p.domination_count = 0 p.dominated_set = [] for q in population: if p == q: continue # Check if p dominates q (lower val_loss, max_dd, tracking_jitter) if (p.val_loss <= q.val_loss and p.max_dd <= q.max_dd and p.tracking_jitter <= q.tracking_jitter) and \ (p.val_loss < q.val_loss or p.max_dd < q.max_dd or p.tracking_jitter < q.tracking_jitter): if q not in p.dominated_set: p.dominated_set.append(q) elif (q.val_loss <= p.val_loss and q.max_dd <= p.max_dd and q.tracking_jitter <= p.tracking_jitter) and \ (q.val_loss < p.val_loss or q.max_dd < p.max_dd or q.tracking_jitter < p.tracking_jitter): p.domination_count += 1 if p.domination_count == 0: p.pareto_rank = 0 fronts[0].append(p) i = 0 while len(fronts[i]) > 0: next_front = [] for p in fronts[i]: for q in p.dominated_set: q.domination_count -= 1 if q.domination_count == 0: q.pareto_rank = i + 1 next_front.append(q) i += 1 fronts.append(next_front) return [f for f in fronts if len(f) > 0] def select_parent(self, population): tournament = random.sample(population, k=3) return min(tournament, key=lambda ind: (ind.pareto_rank, ind.val_loss)) def crossover(self, parent1, parent2): alpha = random.random() child_dna = [ parent1.dna[0], alpha * parent1.dna[1] + (1 - alpha) * parent2.dna[1], alpha * parent1.dna[2] + (1 - alpha) * parent2.dna[2], alpha * parent1.dna[3] + (1 - alpha) * parent2.dna[3] ] return Individual(child_dna) def mutate(self, individual): if random.random() < self.mutation_rate: individual.dna[1] = max(5.0, min(60.0, individual.dna[1] + random.gauss(0, 3.0))) if random.random() < self.mutation_rate: individual.dna[2] = max(0.0001, min(0.01, individual.dna[2] + random.gauss(0, 0.0005))) if random.random() < self.mutation_rate: individual.dna[3] = max(0.0, min(1.0, individual.dna[3] + random.gauss(0, 0.1))) return individual # ============================================================================== # 2. WALK-FORWARD VALIDATION & BROKER PAPER EXECUTION SIMULATOR # ============================================================================== class WalkForwardValidationEngine: """Rolling out-of-sample validation to prevent overfitting.""" def __init__(self, n_splits=3, train_ratio=0.7): self.n_splits = n_splits self.train_ratio = train_ratio def validate_strategy_robustness(self, elite_individual, market_matrix): if elite_individual is None: return elite_individual, 0.0 total_rows = len(market_matrix) fold_size = total_rows // self.n_splits is_sharpes, oos_sharpes = [], [] for i in range(self.n_splits): start_idx = i * fold_size end_idx = start_idx + fold_size if i < self.n_splits - 1 else total_rows fold = market_matrix.iloc[start_idx:end_idx].reset_index(drop=True) split_pt = int(len(fold) * self.train_ratio) train_f, test_f = fold.iloc[:split_pt], fold.iloc[split_pt:] if len(train_f) > 30 and len(test_f) > 30: tr_ind, _ = MultiFactorChannelEvaluationNode.evaluate_channel_strategy(Individual(elite_individual.dna.copy()), train_f) te_ind, _ = MultiFactorChannelEvaluationNode.evaluate_channel_strategy(Individual(elite_individual.dna.copy()), test_f) is_sharpes.append(-tr_ind.val_loss if tr_ind.val_loss < 900 else 0.0) oos_sharpes.append(-te_ind.val_loss if te_ind.val_loss < 900 else 0.0) mean_is = np.mean(is_sharpes) if is_sharpes else 1.0 mean_oos = np.mean(oos_sharpes) if oos_sharpes else 0.0 return elite_individual, (mean_oos / mean_is if mean_is > 0 else 0.0) class BrokerExecutionSimulator: """ Translates validated strategy genotypes into live paper-trading order matrices, simulating order fill latency, slippage, and position reconciliation. """ @staticmethod def simulate_live_order_routing(dna_vector, market_matrix, starting_cash=100000.0): ind = Individual(dna_vector) _, signal = MultiFactorChannelEvaluationNode.evaluate_channel_strategy(ind, market_matrix) if signal is None: return pd.DataFrame(), starting_cash prices = market_matrix['SPY_close'].values[-len(signal):] cash = starting_cash position = 0.0 portfolio_history = [] for idx, (p, sig) in enumerate(zip(prices, signal)): # Simulate slippage & latency fill fill_price = p * (1.0 + 0.0001 * np.sign(sig)) target_pos = sig * 100 # Share allocation scalar trade_action = "HOLD" if target_pos != position: trade_action = "BUY" if target_pos > position else "SELL" cash -= (target_pos - position) * fill_price position = target_pos portfolio_value = cash + (position * p) portfolio_history.append({ "Tick": idx, "Price": p, "Signal": sig, "Action": trade_action, "Fill Price": fill_price, "Position Shares": position, "Portfolio Value": portfolio_value }) return pd.DataFrame(portfolio_history), portfolio_history[-1]["Portfolio Value"] if portfolio_history else starting_cash # ============================================================================== # 3. SQLITE PERSISTENCE LAYER # ============================================================================== class GeneticPersistenceLayer: def __init__(self, db_path="./deployment_compiled/swarm_enterprise.db"): self.db_path = db_path if os.path.dirname(self.db_path): os.makedirs(os.path.dirname(self.db_path), exist_ok=True) self._init_schema() def _init_schema(self): with sqlite3.connect(self.db_path) as conn: conn.execute(''' CREATE TABLE IF NOT EXISTS enterprise_elites ( id INTEGER PRIMARY KEY AUTOINCREMENT, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP, sharpe_ratio REAL, max_drawdown REAL, tracking_jitter REAL, oos_degradation REAL, pareto_rank INTEGER, dna_vector TEXT ) ''') conn.commit() def persist_elite(self, elite, oos_deg=1.0): if elite is None: return sharpe = -elite.val_loss if elite.val_loss < 900 else 0.0 with sqlite3.connect(self.db_path) as conn: conn.execute(''' INSERT INTO enterprise_elites (sharpe_ratio, max_drawdown, tracking_jitter, oos_degradation, pareto_rank, dna_vector) VALUES (?, ?, ?, ?, ?, ?) ''', (sharpe, elite.max_dd, elite.tracking_jitter, oos_deg, elite.pareto_rank, json.dumps(elite.dna))) conn.commit() @staticmethod def load_elites(db_path="./deployment_compiled/swarm_enterprise.db"): try: with sqlite3.connect(db_path) as conn: return pd.read_sql_query("SELECT * FROM enterprise_elites ORDER BY sharpe_ratio DESC", conn) except Exception: return pd.DataFrame() # ============================================================================== # 4. STREAMLIT ENTERPRISE UI CONTROL CENTER # ============================================================================== st.set_page_config(page_title="Janus Protocol | Enterprise Swarm & Broker Platform", page_icon="⚡", layout="wide") st.title("⚡ Janus Protocol: Enterprise Evolutionary Swarm & Broker Platform") st.markdown("Multi-Objective NSGA-II Optimization, Volatility Regime Classification, Walk-Forward Validation, and Live Broker Paper Routing.") st.markdown("---") DB_PATH = "./deployment_compiled/swarm_enterprise.db" persistence = GeneticPersistenceLayer(db_path=DB_PATH) st.sidebar.header("🛸 Enterprise Swarm Panel") pop_size = st.sidebar.slider("Population Size", 20, 100, 40, 5) gens = st.sidebar.slider("Generations Loop", 2, 20, 5, 1) ticks = st.sidebar.slider("Market Ticks Density", 500, 3000, 1500, 250) if st.sidebar.button("🚀 Run NSGA-II Swarm Optimization"): with st.sidebar.status("Executing parallel optimization and regime classification...", expanded=True) as status: st.write("Generating macro synthetic price data & regime tags...") np.random.seed(int(time.time())) random.seed(int(time.time())) prices = 400.0 + np.cumsum(np.random.normal(0, 0.4, ticks)) market_matrix = pd.DataFrame({'SPY_close': prices}) optimizer = EvolutionaryChannelOptimizer(population_size=pop_size, generations=gens) pop = optimizer.initialize_population() best_elite = None for g in range(gens): evaluated = optimizer.evaluate_population(pop, market_matrix) fronts = optimizer.fast_non_dominated_sort(evaluated) fronts[0].sort(key=lambda x: x.val_loss) if best_elite is None or fronts[0][0].val_loss < best_elite.val_loss: best_elite = fronts[0][0] st.write(f"Generation {g+1:02d} | Pareto Front Size: {len(fronts[0])} | Best Loss: {fronts[0][0].val_loss:.4f}") next_pop = fronts[0][:int(pop_size * 0.4)] while len(next_pop) < pop_size: p1 = optimizer.select_parent(evaluated) p2 = optimizer.select_parent(evaluated) child = optimizer.crossover(p1, p2) child = optimizer.mutate(child) next_pop.append(child) pop = next_pop st.write("Running Walk-Forward Robustness Validation...") wf = WalkForwardValidationEngine() _, oos_deg = wf.validate_strategy_robustness(best_elite, market_matrix) persistence.persist_elite(best_elite, oos_deg) status.update(label="Enterprise Pipeline Completed Successfully!", state="complete", expanded=False) st.sidebar.success("Database synchronized.") df_elites = GeneticPersistenceLayer.load_elites(db_path=DB_PATH) if df_elites.empty: st.warning("⚠️ No enterprise records found. Use the sidebar control panel to trigger the NSGA-II optimization engine.") else: tab1, tab2, tab3 = st.tabs(["🧬 Swarm & Pareto Front", "🌊 Volatility Regimes", "⚡ Live Broker Paper Simulator"]) with tab1: c1, c2, c3, c4 = st.columns(4) c1.metric("Total Elites", f"{len(df_elites)}") c2.metric("Peak Sharpe", f"{df_elites['sharpe_ratio'].max():.4f}") c3.metric("Min Drawdown", f"{df_elites['max_drawdown'].min():.2f}%") c4.metric("Avg Generalization", f"{df_elites['oos_degradation'].mean():.2f}x") st.markdown("### 📊 Evolved Elites Performance Registry") st.dataframe(df_elites, use_container_width=True) selected_idx = st.selectbox("Select Strategy Elite Rank for Inspection", options=range(len(df_elites))) row = df_elites.iloc[selected_idx] dna = json.loads(row['dna_vector']) st.code(f""" Chromosome DNA Vector: - Indicator Flag : {dna[0]} - Lookback Window : {dna[1]:.2f} - Breakout Threshold : {dna[2]:.5f} - Channel Weight : {dna[3]:.4f} """) with tab2: st.markdown("### 🌊 Macro Volatility Regime Breakdown") st.markdown("Unsupervised structural tagging of price history into trending versus high-volatility shock regimes.") sample_prices = 400.0 + np.cumsum(np.random.normal(0, 0.4, 1000)) sample_matrix = pd.DataFrame({'SPY_close': sample_prices}) classified_df = VolatilityRegimeClassifier.classify_regimes(sample_matrix) st.line_chart(classified_df[['SPY_close', 'volatility']]) st.dataframe(classified_df.tail(20), use_container_width=True) with tab3: st.markdown("### ⚡ Broker Paper Execution & Order Routing Simulator") st.markdown("Simulating live API execution fills, slippage, and position tracking using selected elite strategy parameters.") if not df_elites.empty: sim_dna = json.loads(df_elites.iloc[0]['dna_vector']) sim_prices = 400.0 + np.cumsum(np.random.normal(0, 0.4, 500)) sim_matrix = pd.DataFrame({'SPY_close': sim_prices}) exec_df, final_val = BrokerExecutionSimulator.simulate_live_order_routing(sim_dna, sim_matrix) col_res1, col_res2 = st.columns(2) col_res1.metric("Initial Paper Capital", "$100,000.00") col_res2.metric("Simulated Terminal Equity", f"${final_val:,.2f}") st.markdown("#### Live Execution Order Ledger") st.dataframe(exec_df, use_container_width=True) st.markdown("#### Portfolio Equity Growth Curve") st.line_chart(exec_df.set_index("Tick")["Portfolio Value"]) 